  psi_lo = inp->comp_grid->lower[NPSI] + (inp->local.lower[NPSI] - inp->global.lower[NPSI])*inp->comp_grid->dx[NPSI];
  psi_up = inp->comp_grid->lower[NPSI] + (inp->local.upper[NPSI] - inp->global.lower[NPSI])*inp->comp_grid->dx[NPSI];

