        g->dual[1].x[0] = 0;
        g->dual[1].x[1] = 1.0/(rz[0]*rz[0]);
        g->dual[1].x[2] = 0.0;

        // e^3 is just sigma_3
        g->dual[2].x[0] = 0;
        g->dual[2].x[1] = 0.0;
        g->dual[2].x[2] = 1.0 / dZ_dz;  

