    fout[0] = - poly_order * pow(z - right, poly_order-1)/fabs(pow(left-right, poly_order-1));
  else
    fout[0] = 1.0;
}

void
test_identity_position_map(double t, const double *GKYL_RESTRICT xn, double *GKYL_RESTRICT fout, void *ctx)
{
