  // create mirror geometry
  struct gkyl_mirror_grid_gen *geom =
    gkyl_mirror_grid_gen_inew(&(struct gkyl_mirror_grid_gen_inp) {
        .comp_grid = &comp_grid,
        .nrange = node_range,
        .local = range,
        .global = range,

        .R = { psi_grid.lower[0], psi_grid.upper[0] },
        .Z = { psi_grid.lower[1], psi_grid.upper[1] },

