    double g01 = gkyl_vec3_dot(
        gkyl_vec3_polar_con_to_cart(rz[0], 0.0, g->tang[0]),
        gkyl_vec3_polar_con_to_cart(rz[0], 0.0, g->tang[1])
    );
    double g02 = gkyl_vec3_dot(
