            gFld_n[count] = tanvecFld_n[3*i+0]*tanvecFld_n[3*j+0] + tanvecFld_n[3*i+1]*tanvecFld_n[3*j+1] + tanvecFld_n[3*i+2]*tanvecFld_n[3*j+2];
