        double J = jFld_n[0];
        double phi = mc2p_n[PHI_IDX];

        // Calculate cmag, bi, and jtot_inv
        biFld_n[0] = gFld_n[2]/sqrt(gFld_n[5]);
        biFld_n[1] = gFld_n[4]/sqrt(gFld_n[5]);
        biFld_n[2] = gFld_n[5]/sqrt(gFld_n[5]);

