        double norm3 = sqrt(dualFld_n[6]*dualFld_n[6] + dualFld_n[7]*dualFld_n[7] + dualFld_n[8]*dualFld_n[8]);

        dualmagFld_n[0] = norm1;
        dualmagFld_n[1] = norm2;
