struct gkyl_mirror_grid_gen *gkyl_mirror_grid_gen_int_inew(const struct gkyl_mirror_grid_gen_inp *inp);

struct gkyl_mirror_grid_gen *gkyl_mirror_grid_gen_surf_inew(const struct gkyl_mirror_grid_gen_inp *inp);

