  double dBdR = 0.0, dBdZ = 0.0;
  double dBrdR = 0.0, dBrdZ = 0.0;
  double dBzdR = 0.0, dBzdZ = 0.0;

  double xn[2] = {r_curr, Z};
  double fout[4];
  evcub->eval_cubic_wgrad(0.0, xn, fout, evcub->ctx);
  dpsidR = fout[1];
  dpsidZ = fout[2];
  evcub->eval_cubic_wgrad2(0.0, xn, fout, evcub->ctx);
  d2psidR2 = fout[1];
