  d2psidRdZ = fout[3];

  Br = 1.0/r_curr*dpsidZ;
  Bz = -1.0/r_curr*dpsidR;
  bmag = sqrt(Br*Br+Bz*Bz);

  dBrdR  = 1.0/r_curr*d2psidRdZ;
