  for (int kind=-2; kind<3; ++kind) { // Interior, corners, then each surface orientation.
    struct gkyl_mirror_grid_gen *full = 0;
    struct gkyl_range full_nodes;
    for (int cuts=1; cuts<=8; cuts*=2) {
      for (int rank=0; rank<cuts; ++rank) {
