text(await tools.exec_command({cmd:"python - <<'PY'
from pathlib import Path
p=Path('gyrokinetic/zero/efit.c')
s=p.read_text().replace('      double *fpol_n = gkyl_array_fetch(fpolflux_n, gkyl_range_idx(&flux_nrange, fidx));\n      fpolprime_n[0] = fpolprime_n[0]/fpol_n[0]; // divide out fpol\n','')
needle='  gkyl_nodal_ops_n2m(n2m_flux, &up->fluxbasis, &up->fluxgrid, \n    &flux_nrange, &up->fluxlocal, 1, fpolprimeflux_n, up->fpolprimeflux, false);'
insert='''  // FF'/F is undefined where F vanishes (including a purely poloidal
  // field). There use the derivative of the tabulated F itself.
  double dpsi_node = (fluxupper[0]-fluxlower[0])/(up->nr-1);
  for (int i=0; i<up->nr; ++i) {
    const double *fpol_n = gkyl_array_cfetch(fpolflux_n, i);
    double *fpolprime_n = gkyl_array_fetch(fpolprimeflux_n, i);
    if (fpol_n[0] != 0.0)
      fpolprime_n[0] /= fpol_n[0];
    else {
      int left = i==0 ? 0 : i-1, right = i==up->nr-1 ? i : i+1;
      const double *fleft = gkyl_array_cfetch(fpolflux_n, left);
      const double *fright = gkyl_array_cfetch(fpolflux_n, right);
      fpolprime_n[0] = (fright[0]-fleft[0])/((right-left)*dpsi_node);
    }
  }
'''
assert needle in s
s=s.replace(needle,insert+needle)
p.write_text(s)
