            double radius = rz[0], height = rz[1], bz = 1.0+height*height, br = -radius*height;
            double bmag = sqrt(br*br+bz*bz), dbdr = radius*height*height/bmag;
            double dbdz = (radius*radius*height+2.0*height*bz)/bmag;
