            double dbdz = (radius*radius*height+2.0*height*bz)/bmag;
            double curl_phi = -radius/bmag + (dbdr*bz-dbdz*br)/(bmag*bmag);
            curl_error = fmax(curl_error, fabs(radius*geo->curlbhat.x[1]-curl_phi));
            double tangent_len = sqrt(geo->tang[2].x[0]*geo->tang[2].x[0]+geo->tang[2].x[2]*geo->tang[2].x[2]);
            double normal_field = bmag/(tangent_len*fabs(geo->dual[2].x[2]));
            normal_field_error = fmax(normal_field_error, fabs(normal_field-bz));
            jacobian_error = fmax(jacobian_error, fabs(geo->Jc-expected_jac));
            partition_error = fmax(partition_error, fabs(geo->Jc-ref->Jc));
            // Reciprocal bases, including the constant-psi field-line tangent.
            for (int idir=0; idir<3; ++idir) {
              for (int jdir=0; jdir<3; ++jdir) {
                double dot = geo->tang[idir].x[0]*geo->dual[jdir].x[0]
                  + rz[0]*rz[0]*geo->tang[idir].x[1]*geo->dual[jdir].x[1]
                  + geo->tang[idir].x[2]*geo->dual[jdir].x[2];
                if (radius>0.0) tangent_error = fmax(tangent_error, fabs(dot-(idir==jdir)));
              }
            }
          }
          if (cuts!=1) gkyl_mirror_grid_gen_release(geom);
        }
      }
      gkyl_mirror_grid_gen_release(full);
    }
  }
  TEST_CHECK(slope_error < 2e-11); TEST_MSG("mapping slope error %.17g", slope_error);
  TEST_CHECK(tangent_error < 2e-13); TEST_MSG("reciprocal basis error %.17g", tangent_error);
  TEST_CHECK(jacobian_error < 2e-10); TEST_MSG("Jacobian error %.17g", jacobian_error);
  TEST_CHECK(curl_error < 2e-10); TEST_MSG("curl error %.17g", curl_error);
  TEST_CHECK(normal_field_error < 2e-10); TEST_MSG("normal B error %.17g", normal_field_error);
  TEST_CHECK(partition_error < 2e-12); TEST_MSG("partition error %.17g", partition_error);
  gkyl_position_map_release(pmap);
  gkyl_array_release(psi);
