  struct gkyl_basis_ops_evalf *evcub = gkyl_dg_basis_ops_evalf_new(&gridRZ, inp->psiRZ);
  if (inp->write_psi_cubic)
    gkyl_dg_basis_ops_evalf_write_cubic(evcub, inp->psi_cubic_fname ? inp->psi_cubic_fname : "psi_cubic.gkyl");

